function localToday(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function parseCalendar(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return null;let [y,m,d]=value.split('-').map(Number);if(y<1900||y>9999)return null;let date=new Date(Date.UTC(y,m-1,d));return date.getUTCFullYear()===y&&date.getUTCMonth()===m-1&&date.getUTCDate()===d?date:null}function calendarFormat(d){return d.toLocaleDateString('pt-BR',{timeZone:'UTC'})}
