if(key==='conversor-unidades'){function convertUnits(){let category=by('unitcategory').value,data=unitData[category],v=Number(by('unitvalue').value),f=by('unitfrom').value,t=by('unitto').value;if(!by('unitvalue').value||!Number.isFinite(v)){by('unitresult').textContent='Informe um valor numérico válido.';return}let result;if(category==='temperature'){let c=f==='C'?v:f==='F'?(v-32)*5/9:v-273.15;if(c< -273.150000001){by('unitresult').textContent='Temperatura abaixo do zero absoluto.';return}result=t==='C'?c:t==='F'?c*9/5+32:c+273.15}else result=v*data.find(x=>x[0]===f)[2]/data.find(x=>x[0]===t)[2];let display=Number.isFinite(result)?(result!==0&&(Math.abs(result)<.00000001||Math.abs(result)>=1e15)?result.toExponential(8):result.toLocaleString('pt-BR',{maximumFractionDigits:8})):'fora do limite numérico';by('unitresult').textContent=`${v.toLocaleString('pt-BR')} ${data.find(x=>x[0]===f)[1]} = ${display} ${data.find(x=>x[0]===t)[1]}`}function changeCategory(){let options=unitData[by('unitcategory').value].map(([id,label])=>`<option value="${id}">${label}</option>`).join('');by('unitfrom').innerHTML=by('unitto').innerHTML=options;by('unitto').selectedIndex=1;convertUnits()}by('unitcategory').onchange=changeCategory;['unitvalue','unitfrom','unitto'].forEach(id=>by(id).addEventListener('input',convertUnits));by('swapunits').onclick=()=>{let v=by('unitfrom').value;by('unitfrom').value=by('unitto').value;by('unitto').value=v;convertUnits()};changeCategory()}
