if(key==='base64'){function invalidate64(){by('baseoutput').value='';by('copy64').disabled=true;by('basestatus').textContent='Escolha Codificar ou Decodificar.'}by('baseinput').oninput=invalidate64;function process64(decode){try{let input=by('baseinput').value;if(!input)throw Error('Informe o conteúdo de entrada.');if(input.length>1000000)throw Error('Limite de 1 milhão de caracteres.');let output;if(decode){let clean=input.replace(/\s/g,'');if(!clean||!/^[A-Za-z0-9+/]*={0,2}$/.test(clean)||clean.length%4===1||(clean.includes('=')&&clean.length%4!==0))throw Error('Base64 padrão inválido.');let bin=atob(clean),bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));output=new TextDecoder('utf-8',{fatal:true}).decode(bytes)}else{let bytes=new TextEncoder().encode(input),binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));output=btoa(binary)}by('baseoutput').value=output;by('basestatus').textContent=decode?'Texto decodificado em UTF-8.':'Texto codificado em Base64.';by('copy64').disabled=false}catch(e){by('baseoutput').value='';by('copy64').disabled=true;by('basestatus').textContent='Não foi possível converter: '+e.message}}by('encode64').onclick=()=>process64(false);by('decode64').onclick=()=>process64(true);by('clear64').onclick=()=>{by('baseinput').value='';invalidate64()};by('copy64').onclick=()=>copyValue(by('baseoutput').value,'basestatus')}

